style.css:
@-moz-document domain("terabox.com") {
/* General elements */
    * {
        background-color: #000000 !important; /* Black background */
        color: inherit !important; /* Preserve text color unless specified */
    }

    /* Default text */
    body, html, div, section, p, span, a, h1, h2, h3, h4, h5, h6, li {
        background-color: #000000 !important; /* Force black */
        color: #ffffff !important; /* White text */
    }

    /* Links */
    a, a:visited {
        color: #9370db !important; /* Light purple links */
    }
    a:hover {
        color: #ba55d3 !important; /* Brighter purple on hover */
    }

    /* Dropdowns and select menus */
    select, .dropdown, .dropdown-menu {
        background-color: #301934 !important; /* Dark purple */
        color: #ffffff !important; /* White text */
        border: 1px solid #553c61 !important; /* Purple border */
    }

    /* Dropdown items */
    .dropdown-item {
        background-color: #301934 !important; /* Dark purple */
        color: #ffffff !important; /* White text */
    }
    .dropdown-item:hover {
        background-color: #402344 !important; /* Slightly brighter dark purple */
        color: #ffffff !important;
    }

    /* Inputs and form elements */
    input, textarea, button {
        background-color: #301934 !important; /* Dark purple */
        color: #ffffff !important;
        border: 1px solid #553c61 !important;
    }
    input::placeholder, textarea::placeholder {
        color: #bb99cc !important; /* Light lavender placeholders */
    }

    /* Tables */
    table, th, td {
        background-color: #20122a !important; /* Slightly lighter black */
        color: #ffffff !important; /* White text */
        border: 1px solid #553c61 !important; /* Purple border */
    }

    /* Interactive elements */
    button:hover, .btn:hover, a:hover, .dropdown-item:hover {
        background-color: #402344 !important; /* Slightly brighter dark purple */
        color: #ffffff !important;
    }

    /* Preserve icons and pictograms */
    img, svg, i {
        filter: none !important; /* Preserve original colors */
        background-color: transparent !important; /* No background */
    }

    /* Modals, popups, and overlays */
    .modal, .popup, .overlay, .sidebar {
        background-color: #000000 !important; /* Black background */
        color: #ffffff !important; /* White text */
    }

    /* Scrollbars */
    ::-webkit-scrollbar {
        width: 8px;
        background-color: #000000 !important; /* Black scrollbar */
    }
    ::-webkit-scrollbar-thumb {
        background-color: #553c61 !important; /* Purple thumb */
    }
}
